# Merch Forge · local provider readiness doctor (NO network call, NO image generation)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Modules\Forge.GenerationAuthority.ps1')
function V($o,[string]$n){if($null-eq$o){return $null};$p=$o.PSObject.Properties[$n];if($null-eq$p){return $null};return $p.Value}
function GetSecret([string]$Path){$e=([string]$env:OPENAI_API_KEY).Trim();if($e){return [pscustomobject]@{present=$true;source='OPENAI_API_KEY'}};if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return [pscustomobject]@{present=$false;source='none'}};$enc=(Get-Content -LiteralPath $Path -Raw -Encoding UTF8).Trim();if(-not $enc){return [pscustomobject]@{present=$false;source='empty_dpapi'}};try{$sec=$enc|ConvertTo-SecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec);try{$plain=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr);return [pscustomobject]@{present=(-not [string]::IsNullOrWhiteSpace($plain));source='dpapi'}}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)}}catch{return [pscustomobject]@{present=$false;source='dpapi_error'}}}
function WriteAtomic([string]$Path,$Object){$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');$utf8=New-Object Text.UTF8Encoding -ArgumentList $false;[IO.File]::WriteAllText($tmp,($Object|ConvertTo-Json -Depth 20),$utf8);Move-Item -LiteralPath $tmp -Destination $Path -Force}
function PaidToday([string]$AttemptRoot,[string]$Provider){
    if(-not(Test-Path -LiteralPath $AttemptRoot)){return 0};try{$files=@(Get-ChildItem -LiteralPath $AttemptRoot -Filter '*.attempt.json' -File -ErrorAction Stop)}catch{throw ('Provider attempt journal directory cannot be read safely. Paid generation is blocked: '+$_.Exception.Message)};$n=0
    foreach($f in $files){try{$a=Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8|ConvertFrom-Json}catch{throw ('Provider attempt journal is unreadable. Paid generation is blocked: '+$f.Name)};$schema=[string](V $a 'schema');$jobId=[string](V $a 'job_id');$providerKey=[string](V $a 'provider_key');$requestCount=[int](V $a 'provider_request_count');if($schema -ne 'forge.generation_attempt.v1' -or $jobId -notmatch '^gen-[0-9a-f]{32}$' -or [IO.Path]::GetFileName($f.FullName) -ne ($jobId+'.attempt.json') -or [string]::IsNullOrWhiteSpace($providerKey) -or $requestCount -ne 1){throw ('Provider attempt journal is malformed. Paid generation is blocked: '+$f.Name)};try{$dt=[DateTime]::Parse([string](V $a 'dispatch_started_at')).ToUniversalTime()}catch{throw ('Provider attempt journal has an invalid dispatch timestamp. Paid generation is blocked: '+$f.Name)};if($dt -gt [DateTime]::UtcNow.AddMinutes(10)){throw ('Provider attempt journal has a future dispatch timestamp. Paid generation is blocked: '+$f.Name)};if($providerKey -eq $Provider -and $dt.Date -eq [DateTime]::UtcNow.Date){$n++}}
    return $n
}
function FirstLiveCompleted([string]$StateRoot,[string]$Provider) {
    return (Test-ForgeFirstLiveAuthority $StateRoot $Provider)
}
$root=$PSScriptRoot;$state=Join-Path $env:LOCALAPPDATA 'MerchForge';$reportPath=Join-Path $state 'provider-doctor.json';if(-not(Test-Path $state)){New-Item -ItemType Directory -Path $state -Force|Out-Null}
$checks=@();$ready=$true;$provider='';$message='Ready for an explicit Generate click.';$profile='';$used=0;$daily=0;$firstLive=$false
try{
  $regPath=Join-Path $root 'Data\Forge.GenerationProviders.json';$reg=Get-Content -LiteralPath $regPath -Raw -Encoding UTF8|ConvertFrom-Json;$ok=([string](V $reg 'schema') -eq 'forge.generation_providers.v6');$checks+=,[ordered]@{name='provider_registry_v6';pass=$ok};if(-not $ok){throw 'Provider registry is invalid.'}
  $cfgPath=Join-Path $state 'provider-config.json';if(-not(Test-Path -LiteralPath $cfgPath -PathType Leaf)){$ready=$false;$message='Provider is not configured.';$checks+=,[ordered]@{name='provider_config_present';pass=$false}}else{$checks+=,[ordered]@{name='provider_config_present';pass=$true};$cfg=Get-Content -LiteralPath $cfgPath -Raw -Encoding UTF8|ConvertFrom-Json;$schema=[string](V $cfg 'schema');if($schema -notin @('forge.local_generation_provider_config.v1','forge.local_generation_provider_config.v2','forge.local_generation_provider_config.v3')){throw 'Provider config schema is unsupported.'};$provider=[string](V $cfg 'provider_key');$profile=[string](V $cfg 'profile_key');if(-not $profile){$profile='legacy_custom'};$enabled=[bool](V $cfg 'enabled');$checks+=,[ordered]@{name='provider_explicitly_enabled';pass=$enabled};if(-not $enabled){$ready=$false;$message='Provider is configured but disabled.'};$daily=if($schema -in @('forge.local_generation_provider_config.v2','forge.local_generation_provider_config.v3')){[int](V $cfg 'daily_request_limit')}else{5};if($daily-lt1 -or $daily-gt20){throw 'Daily request ceiling is outside 1..20.'}}
  if($ready){$def=@($reg.providers|Where-Object{[string](V $_ 'provider_key') -eq $provider})|Select-Object -First 1;if($null -eq $def){throw 'Configured provider is missing from the registry.'};$endpoint=([string](V $def 'endpoint'));$endpointOk=($endpoint -eq 'https://api.openai.com/v1/images/generations');$checks+=,[ordered]@{name='pinned_https_endpoint';pass=$endpointOk};if(-not $endpointOk){throw 'Provider endpoint is outside the pinned contract.'};$model=[string](V $cfg 'model');$quality=[string](V $cfg 'quality');$size=[string](V $cfg 'size');$background=[string](V $cfg 'background');$format=[string](V $cfg 'output_format');$count=[int](V $cfg 'output_count');$configOk=(@(V $def 'allowed_models') -contains $model) -and (@(V $def 'allowed_quality') -contains $quality) -and (@(V $def 'allowed_output_format') -contains $format) -and $background -eq 'transparent' -and $format -eq 'png' -and $count -ge 1 -and $count -le 4 -and $size -match '^\d{3,4}x\d{3,4}$';$checks+=,[ordered]@{name='render_config_allowlisted';pass=$configOk};if(-not $configOk){throw 'Provider render configuration is outside the allowlist.'};$firstLive=FirstLiveCompleted $state $provider;$firstSafe=$firstLive -or ($profile-eq'smoke' -and $count-eq1 -and $daily-eq1);$checks+=,[ordered]@{name='first_live_safety';pass=$firstSafe;completed=$firstLive;guard_active=(-not $firstLive);required_profile=if($firstLive){''}else{'smoke'}};if(-not $firstSafe){$ready=$false;$message='First live safety is active: use Smoke with daily ceiling 1 until one exact billable live result is successfully imported.'};$cred=GetSecret (Join-Path $state 'provider-secrets\openai-image.sec');$checks+=,[ordered]@{name='credential_decryptable';pass=[bool]$cred.present;source=$cred.source};if(-not [bool]$cred.present){$ready=$false;$message='Provider credential is missing or cannot be decrypted.'};$used=PaidToday (Join-Path $state 'generation-v1\attempts') $provider;$budgetOk=$used -lt $daily;$checks+=,[ordered]@{name='daily_paid_request_ceiling';pass=$budgetOk;used=$used;limit=$daily};if(-not $budgetOk){$ready=$false;$message=('Daily provider request ceiling reached: '+$used+'/'+$daily)}}
  foreach($d in @('generation-v1\outbox','generation-v1\results','generation-v1\attempts','generation-v1\receipts')){$p=Join-Path $state $d;if(-not(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};$test=Join-Path $p ('.write-test-'+[Guid]::NewGuid().ToString('N'));[IO.File]::WriteAllText($test,'ok');Remove-Item -LiteralPath $test -Force;$checks+=,[ordered]@{name=('writable_'+($d-replace'\\','_'));pass=$true}}
}catch{$ready=$false;$message=$_.Exception.Message;$checks+=,[ordered]@{name='doctor_exception';pass=$false;detail=$_.Exception.Message}}
$report=[ordered]@{schema='forge.provider_doctor.v2';ready=$ready;provider_key=$provider;profile_key=$profile;paid_requests_today=$used;daily_request_limit=$daily;network_called=$false;generation_called=$false;first_live_completed=$firstLive;first_live_guard_active=(-not $firstLive);message=$message;checked_at=[DateTime]::UtcNow.ToString('o');checks=$checks};WriteAtomic $reportPath $report;Write-Output ($report|ConvertTo-Json -Depth 20);if($ready){exit 0}else{exit 10}
